-- =====================================================================
--  Garages invités au Grand Bal 2026 — généré depuis le fichier Sarbacane
--  1407 garages. Clé : le numéro de compte Bony (unique).
--  Régénérer avec scripts\importer-garages.ps1, ne pas éditer à la main.
-- =====================================================================
--  Les codes sont dérivés du numéro de compte : réexécuter l'import ne
--  change jamais un code déjà parti dans un emailing.
-- =====================================================================
on conflict (compte) do update set
  nom = excluded.nom, ville = excluded.ville, cp = excluded.cp,
  profil = excluded.profil, email = excluded.email;

select count(*) as garages, count(distinct code) as codes_distincts from public.garages;
